head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > clearRowVisible]<br/>setRowVisible() 메소드로 Body 영역에서 숨겨진 Row 를 모두 표시합니다.",
    "validation" : [
        "clearRowVisible() 메소드는 개별 Row 의 숨김 해제가 아닌 전체 숨김 해제입니다. (setRowVisible() 로 숨겨진 여러 Row 가 한 번에 모두 표시됩니다.)",
        "clearRowVisible() 메소드가 실행되면 스크롤이 최상단으로 이동합니다.",
    ]
}



scwin.gVar = { "hidden" : [] };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (25 Row - 세로 스크롤 확보용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true">';
    let arrNames = ['김철수', '이영희', '박민준', '최서연', '정도윤', '강하은'];
    let arrDept = ['영업1팀', '영업2팀', '개발팀', '인사팀', '재무팀', '기획팀'];
    for (var i = 0; i < 25; i++) {
        strDlt += '<w2:row>';
        strDlt += '<col1><![CDATA[' + (i + 1) + ']]></col1>';
        strDlt += '<col2><![CDATA[' + arrNames[i % arrNames.length] + ']]></col2>';
        strDlt += '<col3><![CDATA[' + arrDept[i % arrDept.length] + ']]></col3>';
        strDlt += '</w2:row>';
    }
    strDlt += '</w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 조건 설정 - RowNum Column 표시 (숨김/표시 시각 확인용)
    let properties = {
        dataList: "data:dlt_bind",
        rowNumVisible: "true",
    };

    let cList = $c.gcm.createCList(properties);

    // 테스트 참고 라벨 (검증 운영 정보) — grp_comp 맨 위에 표시되도록 grid 생성 전에 먼저 생성
    $c.gcm.createLabel('label="[전제] setRowVisible() 로 Row 1, 3, 5 를 초기 숨김 처리\n[절차] (여러 Row 숨김 + 스크롤) 클릭 -> Row 1,3,5,7,9 숨김 + 스크롤 하단 이동 -> (clearRowVisible) 클릭\n[확인] 숨겼던 Row 전체가 다시 표시(getRowVisible=true) + 스크롤 최상단(getScrollTop=0) 복귀"', '', 'label1');

    // target 생성
    await scwin.createGrid(cList);

    // 초기 숨김 상태 만들기 : Row 1, 3, 5 숨김 (전체 숨김 해제 전제 확보)
    scwin.gVar.hidden = [1, 3, 5];
    target1.setRowVisible(1, false);
    target1.setRowVisible(3, false);
    target1.setRowVisible(5, false);
}



// 일반 그리드(custom 셀 불필요) 동적 생성
scwin.createGrid = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" displayType="label"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" displayType="label"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" displayType="label"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 전제 만들기 : 여러 Row 숨김 + 스크롤 하단 이동 (clearRowVisible 의 전체 표시/최상단 복귀 검증용)
scwin.btn_hideRows_onclick = function () {
    let arrHide = [1, 3, 5, 7, 9];
    for (var i = 0; i < arrHide.length; i++) {
        target1.setRowVisible(arrHide[i], false);
    }
    scwin.gVar.hidden = arrHide;

    // 세로 스크롤을 하단으로 이동 (clearRowVisible 실행 시 최상단 복귀 확인용)
    target1.setScrollTop(200);

    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("[전제] Row " + arrHide.join(', ') + " 숨김 + 스크롤 하단 이동 (scrollTop=" + target1.getScrollTop() + ")");
    }, 300);
}



// clearRowVisible : 숨겨진 Row 를 모두 표시 + 스크롤 최상단 이동 (메인 검증)
scwin.btn_clearRowVisible_onclick = function () {
    target1.clearRowVisible();

    setTimeout(function () {
        // 전체 Row 표시 여부 (숨겨진 Row 가 하나도 없는지) — validation 1
        let allVisible = true;
        for (var i = 0; i < 25; i++) {
            if (target1.getRowVisible(i) !== true) {
                allVisible = false;
                break;
            }
        }

        wf_body_bottom.getObj("scwin").setReturnValue("[전체 Row 표시 여부] " + allVisible);
        wf_body_bottom.getObj("scwin").setReturnValue("[스크롤 최상단 이동 여부] " + (target1.getScrollTop() === 0));
    }, 300);
}
